//! Domain modules depend on repository ports; they must not import or construct infrastructure adapters.
use crate::domain::repository::{Order, OrderRepository};
pub fn place_order<R: OrderRepository>(repository: &R, order: Order) { repository.save(order); }

// Symbol index grows with project; get runs for each reference resolution.
struct Cache { entries: Vec<(String, String)> }
impl Cache { fn get(&self, key: &str) -> Option<&str> { self.entries.iter().find(|(k,_)| k == key).map(|(_,v)| v.as_str()) } }

//! Domain modules depend on repository ports; they must not import or construct infrastructure adapters.
use crate::infra::postgres::repository::PgRepository;
use crate::domain::repository::Order;
pub fn place_order(order: Order) { let db = PgRepository::connect(); db.save(order); }

pub struct PgRepository;
impl PgRepository { pub fn connect() -> Self { Self } }
impl crate::domain::repository::OrderRepository for PgRepository { fn save(&self, _order: crate::domain::repository::Order) {} }

fn contains(items: &[String], wanted: &[String]) -> bool {
    let set: std::collections::HashSet<_> = items.iter().collect();
    wanted.iter().all(|w| set.contains(w))
}

// Inputs are unbounded; this runs for every requested key.
fn contains(items: &[String], wanted: &[String]) -> bool {
    wanted.iter().all(|w| items.iter().any(|item| item == w))
}

